import {options} from './business.js';
export function showroomMarkup(path='/fleet'){
 const category=['Sedan','SUV','Sprinter'].find(c=>path.endsWith('/'+c.toLowerCase()))||'Sedan';
 return `<section class="private-showroom" aria-labelledby="showroom-heading"><div class="showroom-topline"><div><span class="eyebrow">THE PRIVATE SHOWROOM</span><h1 id="showroom-heading">Choose your arrival.</h1></div><span class="concept-tag">REPRESENTATIVE 3D MODELS · TEMPORARY PREVIEWS</span></div><div class="showroom-experience"><div class="model-zone"><div id="model-host" class="model-host"><div class="model-loading" role="status"><span class="eyebrow">THE COLLECTION</span><strong id="model-loading-label">Luxury ${category}</strong><p>Preparing your private showroom…</p></div></div><div class="model-hint">DRAG TO EXPLORE · A VEHICLE CATEGORY PREVIEW</div><div class="inspection-controls" role="group" aria-label="Vehicle inspection"><button type="button" data-view="front">Front</button><button type="button" data-view="side">Side</button><button type="button" data-view="rear">Rear</button><button type="button" id="rotation-toggle" aria-pressed="false">Pause rotation</button><button type="button" id="reset-model">Reset view</button><button type="button" id="zoom-in" aria-label="Zoom in">+</button><button type="button" id="zoom-out" aria-label="Zoom out">−</button></div><div class="model-booking-summary" hidden><span class="eyebrow">YOUR SELECTED VEHICLE CATEGORY</span><h2 id="compact-category">Luxury ${category}</h2><button class="text-button" type="button" id="change-vehicle">Change vehicle</button></div></div><aside class="showroom-copy"><span class="eyebrow" id="showroom-index">01 / 03</span><div class="selector category-tabs" role="group" aria-label="Vehicle category">${['Sedan','SUV','Sprinter'].map(c=>`<button type="button" data-showroom-category="${c}" aria-pressed="${c===category}">${c}</button>`).join('')}</div><div id="showroom-description" aria-live="polite"><h2>Luxury ${category}</h2><p>Explore the collection and choose the service that fits your journey.</p></div><label for="showroom-service">Choose your service</label><select id="showroom-service">${options.map((o,i)=>`<option value="${i}">${o.name} — $${o.price.toFixed(2)}</option>`).join('')}</select><button type="button" class="button select-vehicle" id="select-vehicle">Select This Vehicle</button><div class="category-navigation"><button type="button" id="previous-vehicle">Previous vehicle</button><button type="button" id="next-vehicle">Next vehicle</button></div><p class="caption">Temporary concept models represent the categories only. Exact vehicle make, model, seating and amenities are confirmed with the company.</p><a class="text-link" href="https://www.martinezlogisticsllc.com/appointments">Prefer the direct booking page?</a></aside><section class="reservation-panel" hidden aria-labelledby="reservation-heading"><button type="button" class="text-button" id="back-to-showroom">Back to the showroom</button><span class="eyebrow">YOUR JOURNEY / LIVE RESERVATIONS</span><h2 id="reservation-heading" tabindex="-1">Make it your journey.</h2><p id="reservation-service-label"></p><label for="booking-service">Selected service</label><select id="booking-service">${options.map((o,i)=>`<option value="${i}">${o.name} — $${o.price.toFixed(2)}</option>`).join('')}</select><p class="caption">Select a time and complete the requested journey details in our live Acuity calendar. Your reservation is confirmed only by the booking provider.</p><p class="caption" id="scheduler-status" role="status"></p><div id="scheduler-mount"></div><a id="external-booking" class="text-link" href="https://www.martinezlogisticsllc.com/appointments" target="_blank" rel="noopener noreferrer">Open booking in a new tab</a><p class="caption">Payment information stays with the booking provider. No card details are handled by this website.</p></section></div><noscript><p class="notice">Interactive 3D requires JavaScript. <a href="https://www.martinezlogisticsllc.com/appointments">Use the official booking page</a> to select any of the nine services.</p></noscript></section>`;
}
